<?php require_once __DIR__.'/bootstrap.php'; require_login();$id=(int)($_GET['id']??0);$ep=(int)($_GET['episode']??1);$s=$pdo->prepare('SELECT * FROM anime WHERE id=?');$s->execute([$id]);$a=$s->fetch();if(!$a)exit('Anime not found');$es=$pdo->prepare('SELECT * FROM episodes WHERE anime_id=? AND number=?');$es->execute([$id,$ep]);$episode=$es->fetch();$vs=$pdo->prepare('SELECT * FROM video_sources WHERE anime_id=? AND episode_id=? AND active=1 ORDER BY priority');$vs->execute([$id,$episode['id']??0]);$sources=$vs->fetchAll();$title='Watch '.$a['title'].' Episode '.$ep.' — AniRead';include __DIR__.'/includes/header.php';?><h1><?=e($a['title'])?> <span class="muted">Episode <?=e($ep)?></span></h1><?php if($sources):$v=$sources[0];?><div class="player"><?php if($v['source_type']==='iframe'):?><iframe src="<?=e($v['source_url'])?>" allowfullscreen></iframe><?php else:?><video controls autoplay src="<?=e($v['source_url'])?>"></video><?php endif;?></div><p class="muted">Server: <?=e($v['server_name'])?> · Language: <?=e($v['language'])?></p><div class="actions"><?php foreach($sources as $x):?><a class="btn alt" href="<?=e($x['source_url'])?>" target="_blank"><?=e($x['language'].' · '.$x['server_name'])?></a><?php endforeach;?></div><?php else:?><div class="form"><h2>Streaming source unavailable for this episode.</h2><p class="muted">An administrator must add an authorized source before this episode can be played.</p></div><?php endif;?><section class="section"><h2>Episodes</h2><div class="episode-list"><?php $q=$pdo->prepare('SELECT number FROM episodes WHERE anime_id=? ORDER BY number');$q->execute([$id]);foreach($q as $x):?><a href="?id=<?=$id?>&episode=<?=$x['number']?>">Episode <?=$x['number']?></a><?php endforeach;?></div></section><?php $h=$pdo->prepare('INSERT INTO watch_history(user_id,anime_id,episode_number,updated_at) VALUES(?,?,?,NOW()) ON DUPLICATE KEY UPDATE updated_at=NOW()');$h->execute([user()['id'],$id,$ep]);include __DIR__.'/includes/footer.php';
